content.css:
[data-section-id='service-area-model'] .cms-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; padding: 2rem; background: var(--cms-backgrounds-frost); border-radius: var(--cms-border-radius-card); }
[data-section-id='service-area-model'] .cms-eyebrow { color: var(--cms-colors-primary); font-weight: 700; }
[data-section-id='service-area-model'] .ice-region-list { display: grid; gap: 0.5rem; padding-left: 1rem; }

[data-section-id='service-area-placeholder-grid'] .ice-area-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; }
[data-section-id='service-area-placeholder-grid'] .ice-area-card { padding: 1.25rem; background: var(--cms-colors-surface); border: 1px solid var(--cms-colors-border); border-radius: var(--cms-border-radius-card); }
[data-section-id='service-area-placeholder-grid'] .ice-area-card h3 { color: var(--cms-colors-primary); }

[data-section-id='service-area-city-strategy'] .ice-city-note { width: 100%; border: 1px solid var(--cms-colors-border); border-radius: var(--cms-border-radius-card); background: var(--cms-colors-surface); }
[data-section-id='service-area-city-strategy'] .ice-city-note th { text-align: left; color: var(--cms-colors-primary); }
[data-section-id='service-area-city-strategy'] .ice-city-note th, [data-section-id='service-area-city-strategy'] .ice-city-note td { padding: 1rem; }
